// ------------------------------------------
// Safe Prescription Translation
// ------------------------------------------
// Medicine name, dosage, frequency and duration
// are NEVER generated by AI.
// Unknown translations remain in original text.
// ------------------------------------------

const HINDI_TRANSLATIONS = {
  "The purpose is not explicitly mentioned in the prescription.":
    "दवा का उद्देश्य डॉक्टर ने पर्चे में स्पष्ट रूप से नहीं लिखा है।",

  "Medication instructions are not specified in the prescription.":
    "पर्चे में दवा लेने का तरीका नहीं लिखा है।",

  "No additional doctor's advice is mentioned.":
    "पर्चे में डॉक्टर की कोई अतिरिक्त सलाह नहीं लिखी है।",

  "Take adequate rest.":
    "पर्याप्त आराम करें।",

  "Twice daily":
    "दिन में 2 बार (Twice daily)",

  "Once daily":
    "दिन में 1 बार (Once daily)",

  "Three times daily":
    "दिन में 3 बार (Three times daily)",

  "Four times daily":
    "दिन में 4 बार (Four times daily)",

  "1 tablet":
    "1 टैबलेट (1 tablet)",

  "2 tablets":
    "2 टैबलेट (2 tablets)",

  "3 days":
    "3 दिन (3 days)",

  "5 days":
    "5 दिन (5 days)",

  "7 days":
    "7 दिन (7 days)",

  "10 days":
    "10 दिन (10 days)",

  "14 days":
    "14 दिन (14 days)",

  "30 days":
    "30 दिन (30 days)",
};

function translateExact(text, language) {
  if (!text || typeof text !== "string") {
    return text;
  }

  if (language === "English") {
    return text;
  }

  if (language !== "Hindi") {
    // No unverified AI medical translation.
    // Preserve the original source wording.
    return text;
  }

  // Only replace exact, approved phrases.
  let translated = text;

  const phrases = Object.keys(HINDI_TRANSLATIONS).sort(
    (a, b) => b.length - a.length
  );

  for (const phrase of phrases) {
    translated = translated.replaceAll(
      phrase,
      HINDI_TRANSLATIONS[phrase]
    );
  }

  return translated;
}

async function translatePrescriptionSummary({
  purpose,
  howToTake,
  doctorAdvice,
  language,
}) {
  return {
    purpose: translateExact(purpose, language),
    howToTake: translateExact(howToTake, language),
    doctorAdvice: translateExact(doctorAdvice, language),
  };
}

module.exports = {
  translatePrescriptionSummary,
};